{
  "metadati": {
    "data_sintetica": "2026-04-16",
    "chiave_indagine": null,
    "descrizione": "L'utente, responsabile della Rilevazione sulle tecnologie dell’informazione e della comunicazione nelle imprese (PSN IST-01175), dichiara di non riuscire a recuperare l'accesso perché non può più accedere alla vecchia casella email associata. L'agente suggerisce di sottoporre la richiesta all'assistenza affinché valuti l'aggiornamento del recapito e chiarisce che gli eventuali passaggi successivi devono essere verificati con l'assistenza."
  },
  "conversazione": [
    {
      "sender": "Utente",
      "testo": "Sono il responsabile della Rilevazione sulle tecnologie dell’informazione e della comunicazione nelle imprese, codice PSN IST-01175. Devo recuperare l'accesso al questionario."
    },
    {
      "sender": "Agente",
      "testo": "Ha già effettuato un tentativo di recupero dell'accesso?"
    },
    {
      "sender": "Utente",
      "testo": "Sì, ma non si è risolto perché non ho più accesso alla vecchia casella {{email_1}}. Il mio codice utente è {{cod_utente_1}} e sono {{persona_1}}."
    },
    {
      "sender": "Agente",
      "testo": "Poiché non è accessibile la vecchia casella email, può sottoporre il problema all'assistenza, indicando che è responsabile dell'indagine e chiedendo di valutare l'aggiornamento del recapito."
    },
    {
      "sender": "Utente",
      "testo": "Dopo l'eventuale aggiornamento riceverò un codice per recuperare l'accesso?"
    },
    {
      "sender": "Agente",
      "testo": "I passaggi successivi e la possibilità di risolvere il recupero devono essere verificati con l'assistenza, che valuterà la richiesta relativa al recapito non accessibile."
    }
  ],
  "trattamento_atteso": {
    "mascherare": [
      {
        "segnaposto": "{{cod_utente_1}}",
        "tipo": "COD_UTENTE",
        "sostituzione": "[COD_UTENTE_1]"
      },
      {
        "segnaposto": "{{email_1}}",
        "tipo": "EMAIL",
        "sostituzione": "[EMAIL_1]"
      },
      {
        "segnaposto": "{{persona_1}}",
        "tipo": "PERSON",
        "sostituzione": "[PERSON_1]"
      }
    ],
    "conservare": [
      "Il ruolo di responsabile dell'utente.",
      "Il nome e il codice PSN dell'indagine: Rilevazione sulle tecnologie dell’informazione e della comunicazione nelle imprese, IST-01175.",
      "Il mancato accesso alla vecchia casella email.",
      "Il tentativo di recupero dell'accesso già effettuato e non risolutivo."
    ],
    "motivazione": "Codice utente, indirizzo email e nome identificano o rendono identificabile l'utente e devono essere mascherati. Le informazioni sull'indagine, sul ruolo e sul problema di accesso sono necessarie per comprendere e trattare la richiesta."
  }
}

{
  "metadati": {
    "data_sintetica": "2026-04-21",
    "chiave_indagine": null,
    "descrizione": "L'utente segnala una comunicazione intestata al precedente referente, che non ricopre più il ruolo, e chiede come comunicare il cambio del referente. Chiarisce che il problema riguarda il destinatario della comunicazione e non l'accesso, indicando {{email_1}} come recapito. L'agente suggerisce di sottoporre la segnalazione all'assistenza affinché valuti la richiesta."
  },
  "conversazione": [
    {
      "sender": "Utente",
      "testo": "Abbiamo ricevuto una comunicazione intestata al precedente referente, ma quella persona non ricopre più il ruolo. Come possiamo segnalare il cambio del referente?"
    },
    {
      "sender": "Agente",
      "testo": "Il problema riguarda il destinatario della comunicazione oppure l'accesso a un servizio?"
    },
    {
      "sender": "Utente",
      "testo": "Riguarda il destinatario della comunicazione, non l'accesso. Il recapito che possiamo indicare è {{email_1}}."
    },
    {
      "sender": "Agente",
      "testo": "Potete segnalare all'assistenza il cambio del referente, specificando che la comunicazione è intestata al precedente referente e indicando il recapito {{email_1}}. L'assistenza potrà valutare la richiesta."
    },
    {
      "sender": "Utente",
      "testo": "Va bene, invieremo la segnalazione."
    }
  ],
  "trattamento_atteso": {
    "mascherare": [
      {
        "segnaposto": "{{email_1}}",
        "tipo": "EMAIL",
        "sostituzione": "[EMAIL_1]"
      }
    ],
    "conservare": [
      "cambio del referente",
      "comunicazione intestata al precedente referente"
    ],
    "motivazione": "L'email {{email_1}} è il recapito offerto dall'utente per la segnalazione e deve essere mascherata. I riferimenti al cambio del referente e alla comunicazione intestata al precedente referente descrivono il problema di assistenza e devono essere conservati."
  }
}
